<template><section class="admin-data-page"><header class="admin-page-head"><div><p>CUSTOMER CARE</p><h1>Q&A 답변 관리</h1><span>미답변 문의를 우선 확인하고 고객에게 답변합니다.</span></div><div class="admin-count warning"><strong>{{ unansweredCount }}</strong><span>미답변</span></div></header>
<div class="admin-filter-card"><label><span>검색</span><input v-model.trim="keyword" type="search" placeholder="제목·작성자"></label><label><span>답변 상태</span><select v-model="status"><option value="all">전체</option><option value="pending">미답변</option><option value="done">답변 완료</option></select></label><div class="admin-filter-actions"><button class="admin-btn ghost" @click="resetFilters">초기화</button><button class="admin-btn secondary" :disabled="loading" @click="fetchQnaList"><i class="fa-solid fa-rotate"></i> 새로고침</button></div></div>
<div class="qna-layout"><div class="admin-table-card"><div class="admin-table-toolbar"><div><strong>문의 목록</strong><span>{{ filteredQnas.length }}건 표시</span></div></div><div v-if="error" class="admin-state error"><p>{{ error }}</p><button class="admin-btn ghost" @click="fetchQnaList">다시 시도</button></div><div v-else class="qna-list"><div v-if="loading" class="admin-state compact"><i class="fa-solid fa-spinner fa-spin"></i><p>문의를 불러오는 중입니다.</p></div><div v-else-if="!filteredQnas.length" class="admin-state compact"><i class="fa-regular fa-folder-open"></i><p>조건에 맞는 문의가 없습니다.</p></div><button v-for="item in filteredQnas" :key="item._id" :class="['qna-item',{active:selectedQna?._id===item._id}]" @click="viewDetail(item)"><span class="admin-status" :data-status="item.hasAnswer?'배송완료':'취소중'">{{ item.hasAnswer?'답변 완료':'미답변' }}</span><div><small>{{ item.category||'기타' }} · {{ formatDate(item.createdAt) }}</small><strong>{{ item.title }}</strong><em>{{ item.maskedAuthor||'작성자' }}</em></div><i class="fa-solid fa-chevron-right"></i></button></div></div>
<article class="qna-detail"><div v-if="!selectedQna" class="admin-state"><i class="fa-regular fa-comment-dots"></i><p>왼쪽 목록에서 문의를 선택하세요.</p></div><template v-else><header><div><span>{{ selectedQna.category||'기타' }}</span><h2>{{ selectedQna.title }}</h2><p>{{ selectedQna.maskedAuthor||'작성자' }} · {{ formatDate(selectedQna.createdAt) }}</p></div><button aria-label="선택 닫기" @click="selectedQna=null"><i class="fa-solid fa-xmark"></i></button></header><section class="question"><small>QUESTION</small><p>{{ selectedQna.content }}</p></section><section v-if="selectedQna.hasAnswer" class="existing-answer"><small>ANSWER</small><p>{{ selectedQna.hasAnswer.content }}</p><span>답변자 {{ selectedQna.hasAnswer.adminName||'관리자' }}</span></section><form v-else class="answer-form" @submit.prevent="submitAnswer"><label><span>답변 내용 *</span><textarea v-model.trim="answerContent" rows="9" placeholder="고객에게 전달할 답변을 입력하세요."></textarea><small>{{ answerContent.length }}자</small></label><div class="admin-notice"><i class="fa-solid fa-circle-info"></i><p><span>등록한 답변은 고객에게 바로 표시됩니다. 내용과 맞춤법을 확인해 주세요.</span></p></div><button class="admin-btn primary" :disabled="submitting||!answerContent">{{ submitting?'등록 중':'답변 등록' }}</button></form></template></article></div></section></template>
<script setup>import{computed,onMounted,ref}from"vue";import QnaService from"@/api/QnaService";import AdminService from"@/api/AdminService";import{getStoredToken,getStoredUser}from"@/utils/storage";const qnaList=ref([]),selectedQna=ref(null),answerContent=ref(""),keyword=ref(""),status=ref("pending"),loading=ref(false),submitting=ref(false),error=ref("");const unansweredCount=computed(()=>qnaList.value.filter(q=>!q.hasAnswer).length);const filteredQnas=computed(()=>qnaList.value.filter(q=>{const matchStatus=status.value==="all"||(status.value==="done"?q.hasAnswer:!q.hasAnswer);const word=keyword.value.toLowerCase();return matchStatus&&(!word||[q.title,q.maskedAuthor,q.category].some(v=>String(v||"").toLowerCase().includes(word)))}));const formatDate=value=>{if(!value)return"-";const d=new Date(value);return Number.isNaN(d.getTime())?"-":d.toLocaleDateString("ko-KR")};async function fetchQnaList(){loading.value=true;error.value="";try{const{data}=await QnaService.getQnaList({page:1,size:1000},getStoredToken());qnaList.value=(data.qnas||[]).sort((a,b)=>Boolean(a.hasAnswer)-Boolean(b.hasAnswer)||new Date(b.createdAt)-new Date(a.createdAt));if(selectedQna.value)selectedQna.value=qnaList.value.find(q=>q._id===selectedQna.value._id)||null}catch(err){console.error("Q&A 조회 실패:",err);error.value="문의 목록을 불러오지 못했습니다."}finally{loading.value=false}}function viewDetail(item){selectedQna.value=item;answerContent.value=""}function resetFilters(){keyword.value="";status.value="all"}async function submitAnswer(){if(!selectedQna.value||!answerContent.value)return;const admin=getStoredUser();if(!admin?._id)return alert("관리자 정보를 확인할 수 없습니다. 다시 로그인해 주세요.");if(!confirm("작성한 답변을 등록하시겠습니까?"))return;submitting.value=true;try{await AdminService.answerQna(selectedQna.value._id,{content:answerContent.value,adminId:admin._id},getStoredToken());alert("답변이 등록되었습니다.");await fetchQnaList();status.value="pending";selectedQna.value=null}catch(err){console.error("답변 등록 실패:",err);alert(err.response?.data?.message||"답변을 등록하지 못했습니다.")}finally{submitting.value=false}}onMounted(fetchQnaList);</script>
<style scoped>.qna-layout{display:grid;grid-template-columns:minmax(330px,.8fr) minmax(0,1.2fr);gap:18px}.qna-list{max-height:720px;overflow:auto}.qna-item{width:100%;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:11px;padding:14px;border:0;border-bottom:1px solid #ece5e2;background:#fff;text-align:left;cursor:pointer}.qna-item:hover,.qna-item.active{background:#faf5f6}.qna-item>div{min-width:0;display:grid;gap:4px}.qna-item small,.qna-item em{color:#958a8e;font-size:.59rem;font-style:normal}.qna-item strong{overflow:hidden;font-size:.71rem;text-overflow:ellipsis;white-space:nowrap}.qna-item>i{color:#b3a8ac;font-size:.6rem}.qna-detail{min-height:480px;border:1px solid #e3dcda;background:#fff}.qna-detail>header{display:flex;justify-content:space-between;padding:22px;border-bottom:1px solid #e7dfdc}.qna-detail header span,.qna-detail section>small{color:#a77b87;font-size:.58rem;font-weight:800;letter-spacing:.13em}.qna-detail h2{margin:7px 0;font-family:Georgia,"Noto Serif KR",serif;font-size:1.35rem;font-weight:400}.qna-detail header p{margin:0;color:#958a8e;font-size:.63rem}.qna-detail header button{width:36px;height:36px;border:1px solid #e0d8d5;background:#fff}.qna-detail section{padding:22px}.qna-detail section p{white-space:pre-wrap;font-size:.72rem;line-height:1.9}.existing-answer{margin:0 22px 22px;background:#f7f3f1}.existing-answer span{color:#92878b;font-size:.6rem}.answer-form{display:grid;gap:13px;padding:22px}.answer-form label{display:grid;gap:7px}.answer-form label span{font-size:.67rem;font-weight:700}.answer-form textarea{padding:13px;border:1px solid #ddd4d1;outline:none;resize:vertical;font:inherit;font-size:.72rem}.answer-form label small{text-align:right;color:#9b9194;font-size:.58rem}.answer-form>.admin-btn{justify-self:end}@media(max-width:950px){.qna-layout{grid-template-columns:1fr}.qna-list{max-height:420px}}@media(max-width:600px){.qna-detail>header,.qna-detail section,.answer-form{padding:16px}.existing-answer{margin:0 16px 16px}.answer-form>.admin-btn{width:100%}}</style>
